6	const SPHINX = "sphinx";
7	
8	const SPHINX_BASE_POINTS = 1;
9	
10	// "2 per type beyond three, else 1" — counted over the types a Sphinx can
11	// see, which excludes the Sphinx's own card.
12	const FLAT_VARIETY_POINTS = 1;
13	const VARIETY_POINTS_PER_EXTRA_TYPE = 2;
14	const TYPES_BEFORE_VARIETY_SCALES = 3;
15	
16	const isSphinx = (card: Card): boolean => card.monster === SPHINX;
17	
18	// A card's type is its monster; rank marks a variant (e.g. Undead Warrior
19	// (1) and (3)) and does not make it a separate type.
20	const typeOf = (card: Card): string => card.monster;
21	
22	const countDistinctTypes = (army: Card[]): number =>
23	  new Set(army.map(typeOf)).size;
24	
25	const varietyPoints = (typeCount: number): number => {
26	  const extraTypes = typeCount - TYPES_BEFORE_VARIETY_SCALES;
27	  return extraTypes > 0
28	    ? VARIETY_POINTS_PER_EXTRA_TYPE * extraTypes
29	    : FLAT_VARIETY_POINTS;
30	};
