38	  army.reduce(
39	    (score, card, index) =>
40	      isSphinx(card)
41	        ? score +
42	          SPHINX_BASE_POINTS +
43	          varietyPoints(countDistinctTypes(withoutIndex(army, index)))
44	        : score,
