// A Sphinx counts the types it can see — every card in the army except its
// own. Its own card is the only one it drops, so the type "sphinx" still
// counts whenever some *other* Sphinx is present. That makes the visible
// type count the same for every Sphinx in the army: the army's distinct
// types, minus one for the lone Sphinx that has nobody to vouch for its type.
const typesVisibleToEachSphinx = (army: Card[]): number =>
  countDistinctTypes(army) - (army.filter(isSphinx).length === 1 ? 1 : 0);

// Each Sphinx scores on its own, and they all see the same types.
export const scoreArmy = (army: Card[]): number =>
  army.filter(isSphinx).length *
  (SPHINX_BASE_POINTS + varietyPoints(typesVisibleToEachSphinx(army)));

